def longest_two_distinct(s):
    counts = {}
    left = best = 0
    for right, char in enumerate(s):
        counts[char] = counts.get(char, 0) + 1
        while len(counts) > 2:
            departing = s[left]
            counts[departing] -= 1
            if counts[departing] == 0:
                del counts[departing]
            left += 1
        best = max(best, right - left + 1)
    return best

